# Keep canonical nested ancillary structures when the concrete decision was given as prose.
def restore_nested(value,definition):
    if 'constant' in definition:return definition['constant']
    if 'object' in definition:
        if not isinstance(value,dict):
            statement='；'.join(map(str,value)) if isinstance(value,list) else str(value)
            return {k:restore_nested(statement,c) for k,c in definition['object'].items() if not c.get('optional')}
        for k,c in definition['object'].items():
            if k in value:value[k]=restore_nested(value[k],c)
        return value
    return value
