unresolved=[]
def finalize(node,path):
    if isinstance(node,dict):
        for k,v in node.items():
            if v is None:
                chapter=path.split('.')[0]
                if chapter not in ancillary:unresolved.append(path+'.'+k)
                else:node[k]=ancillary[chapter]
            else:finalize(v,path+'.'+k)
    elif isinstance(node,list):
        for i,v in enumerate(node):finalize(v,path+f'[{i}]')
